import{_ as t,o as e,c as i,a2 as r}from"./chunks/framework.BqDA2HS7.js";const u=JSON.parse('{"title":"第一项任务","description":"","frontmatter":{},"headers":[],"relativePath":"quickstart.md","filePath":"quickstart.md"}'),l={name:"quickstart.md"};function o(s,a,n,c,h,d){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="第一项任务" tabindex="-1">第一项任务 <a class="header-anchor" href="#第一项任务" aria-label="Permalink to &quot;第一项任务&quot;">​</a></h1><p>建议先用 <strong>Static 固定模型</strong> 验证安装、凭证和原生工具，再逐一启用需要 Judge 的策略。 一次运行完成不表示所有策略或 Judge 后端已经通过质量验收。</p><h2 id="_1-先配置-dsh-的真实模型" tabindex="-1">1. 先配置 DSH 的真实模型 <a class="header-anchor" href="#_1-先配置-dsh-的真实模型" aria-label="Permalink to &quot;1. 先配置 DSH 的真实模型&quot;">​</a></h2><p>进入 DSH 的模型设置，配置自己的 provider、端点、模型 ID 与凭证。 Ark Agent Plan 订阅路线使用 <code>/api/plan/v3</code>；普通按量接口按实际 provider 配置。 Router 复用目录与凭证，不另复制一份密钥。</p><p>先用 DSH 的普通模型确认该路线可用。价格、上下文、输出和推理等级以实际路线的资料为准， 不能把另一渠道同名模型的资料直接套用。</p><h2 id="_2-启用规划路由" tabindex="-1">2. 启用规划路由 <a class="header-anchor" href="#_2-启用规划路由" aria-label="Permalink to &quot;2. 启用规划路由&quot;">​</a></h2><p>打开 <strong>设置 → 插件 → RefractAgent 规划路由</strong>：</p><ol><li>启用规划路由，确认正在编辑的是 Static。</li><li>选择“高效执行模型”；当前 Static 固定模式使用这个角色。</li><li>从支持的值中选择推理等级，或选择提供方默认。</li><li>核对数据域；需要发往可信云时登记相应信任策略。</li><li>设置任务现金预算、参考估值额度、期限与调用数。</li><li>运行零调用诊断并保存。</li></ol><p>Static 固定模式不需要强执行、任务 Judge 或审核模型。页面上的通用角色不表示每个策略 都必须配置它们。<a href="./strategies/static.html">Static 的实际设置</a>列出了当前限制。</p><h2 id="_3-选择路由模式并发起任务" tabindex="-1">3. 选择路由模式并发起任务 <a class="header-anchor" href="#_3-选择路由模式并发起任务" aria-label="Permalink to &quot;3. 选择路由模式并发起任务&quot;">​</a></h2><p>在对话模型菜单选择 <strong>RefractAgent · 规划路由</strong>，再在 <strong>路由模式</strong> 中选择 Static。 这里选的是策略，底层模型推理等级使用前一步的角色设置。</p><p>先问一个简单问题，例如 <code>2 + 2</code>。确认回复来自真实模型，且没有 <code>[SIMULATED]</code> 或验收夹具文字。 再提交一个你已允许 DSH 执行工具的短任务，确认工具仍由 DSH 审批与执行。</p><h2 id="_4-检查实际调用" tabindex="-1">4. 检查实际调用 <a class="header-anchor" href="#_4-检查实际调用" aria-label="Permalink to &quot;4. 检查实际调用&quot;">​</a></h2><p>打开 <strong>路由轨迹</strong>，展开本次记录：</p><ul><li>实际 provider、模型、推理等级与用途是否符合固定角色；</li><li>是否只有预期的执行调用，没有额外 Task Judge 或审核；</li><li>工具调用与结果是否配对；</li><li>参考估值、按量现金与待核对预留是否分别列出；</li><li>开始时间、总耗时与首字时间是否可见。</li></ul><h2 id="_5-再试其他路线" tabindex="-1">5. 再试其他路线 <a class="header-anchor" href="#_5-再试其他路线" aria-label="Permalink to &quot;5. 再试其他路线&quot;">​</a></h2><ul><li>工具任务需要逐轮调整模型：<a href="./strategies/stage.html">Stage</a>。</li><li>每个任务从多个模型中选一个：<a href="./strategies/task.html">Task</a>。</li><li>最终回复必须审核与复审：<a href="./strategies/advisor.html">Advisor Gate</a>。</li><li>先尝试起始模型、必要时锁定接管：<a href="./strategies/escalation.html">Escalation</a>。</li><li>Task 初选后允许临时切换：<a href="./strategies/composite.html">Composite</a>。</li><li>研究显式任务拆分：<a href="./automatic.html">自动路由</a>。</li></ul><p>每次新任务冻结设置。运行中的工具续接和追加指导沿用现有预算与计数；保存设置供下个任务使用。</p>',18)])])}const _=t(l,[["render",o]]);export{u as __pageData,_ as default};
